#!/usr/bin/env bash
# GENERATED by hecks deploy project -- re-run it to refresh this file rather than hand-editing.
# Settings come from the domain's deployed_to("AwsBox") block (hosting_scripts true).
#
# Runs the production smoke once a roll of widget-shop's app box has settled, so a deploy ends with a real
# check of the live site instead of waiting for the next scheduled run. Called at the end of
# deploy-service.sh and of `make deploy`; also runnable by hand:
#
#   bash smoke-after-deploy.sh
#
# What it does, in order:
#   1. Waits for the roll to settle: two consecutive checks, one interval apart, must agree that
#      - the box stack and the widget-platform stack are CREATE_COMPLETE or UPDATE_COMPLETE, never rolled back or failed;
#      - every container and the proxy of the box's Compose project is up and has stayed up;
#      - each container runs the image of the task definition it was rolled from (the latest widget-platform unless TASKDEF says otherwise).
#      Gives up after the timeout. The box is read through SSM, the way deploy-box.sh rolls it.
#   2. Dispatches the smoke workflow on the configured ref, finds the run that dispatch created (a
#      workflow_dispatch run that did not exist before the dispatch, never a scheduled one), waits for it,
#      and prints its conclusion, the failed check names and its URL.
#
# It only ever READS AWS; the smoke itself runs on GitHub against the live site.
#
# Exit codes (chosen to stay clear of the ones a failed deploy step produces: 1 from bash, 2 from bash
# misuse, 254/255 from the aws CLI):
#    0  the smoke passed, was skipped on purpose (SKIP_POST_DEPLOY_SMOKE=1), or was left running
#       (SMOKE_ASYNC=1)
#   20  the roll did not settle in time, or a stack ended in a failed state; the smoke was NOT run
#   21  `gh` is missing or not signed in, or no repository is configured; the smoke was NOT run (the
#       manual command is printed)
#   22  the smoke ran and FAILED
#   23  the smoke could not be dispatched, found or finished; result unknown
#
# Environment:
#   SKIP_POST_DEPLOY_SMOKE=1   skip everything and say so
#   SMOKE_ASYNC=1              dispatch the smoke and return as soon as its run is found, printing the
#                              run URL, instead of waiting for it to finish (exit 0: the result is NOT
#                              known yet)
#   DRY_RUN=1                  wait for the roll as usual, then print what would be dispatched without
#                              dispatching anything
#   SETTLE_TIMEOUT_SECS        default 1200
#   SETTLE_CHECK_INTERVAL_SECS default 5
#   SMOKE_RUN_TIMEOUT_SECS     default 1800, how long to wait for the run
#   SSM_POLL_SECS              default 2, how often to ask SSM whether a command on the box finished
#   REPO                       GitHub repository (owner/name) holding the workflow
#   WORKFLOW                   workflow file name
#   SMOKE_REF                  ref to dispatch on
#   TASKDEF                    the task definition the box should run (family or family:revision);
#                              default: the latest revision of the family. deploy-service.sh and
#                              `make deploy TASKDEF=...` pass the one they rolled.
set -uo pipefail

REGION=us-east-1
BOX_STACK=hecks-widget-shop-box
BOX_DIR=/opt/widget-shop
WATCHED_STACKS=hecks-widget-shop-box\ widget-platform
EXPECTED_SERVICES=website\ cms\ domain\ caddy
TASK_DEFINITION="${TASKDEF:-widget-platform}"
REPO="${REPO:-acme/widget-shop}"
WORKFLOW="${WORKFLOW:-smoke-prod.yml}"
SMOKE_REF="${SMOKE_REF:-main}"

SETTLE_TIMEOUT_SECS="${SETTLE_TIMEOUT_SECS:-1200}"
SETTLE_CHECK_INTERVAL_SECS="${SETTLE_CHECK_INTERVAL_SECS:-5}"
SMOKE_RUN_TIMEOUT_SECS="${SMOKE_RUN_TIMEOUT_SECS:-1800}"
SSM_POLL_SECS="${SSM_POLL_SECS:-2}"
MANUAL_COMMAND="bash smoke-after-deploy.sh"

if [ "${SKIP_POST_DEPLOY_SMOKE:-}" = "1" ]; then
  echo "==> post-deploy smoke SKIPPED (SKIP_POST_DEPLOY_SMOKE=1)."
  echo "    Run it yourself when ready: ${MANUAL_COMMAND}"
  exit 0
fi

if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  echo "==> post-deploy smoke NOT RUN: the GitHub CLI (gh) is missing or not signed in." >&2
  echo "    Run it by hand: gh workflow run ${WORKFLOW} --ref ${SMOKE_REF}" >&2
  echo "    or, once gh works: ${MANUAL_COMMAND}" >&2
  exit 21
fi

if [ -z "$REPO" ]; then
  REPO="$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)"
fi
if [ -z "$REPO" ]; then
  echo "==> post-deploy smoke NOT RUN: no GitHub repository is configured. Set REPO=owner/name, or the" >&2
  echo "    smoke_repo setting, or run from a clone gh can read." >&2
  exit 21
fi
MANUAL_DISPATCH="gh workflow run ${WORKFLOW} --repo ${REPO} --ref ${SMOKE_REF}"

# The status of a stack, or nothing when it cannot be read.
stack_status() {
  aws cloudformation describe-stacks --stack-name "$1" --region "$REGION" \
    --query 'Stacks[0].StackStatus' --output text 2>/dev/null
}

# Runs a script on the box over SSM and prints its output; fails when it does not succeed.
box_run() {
  local payload command_id state
  payload="$(jq -n --arg c "$1" '{commands: [$c]}')"
  command_id="$(aws ssm send-command --instance-ids "$BOX_ID" --document-name AWS-RunShellScript \
    --region "$REGION" --parameters "$payload" --query 'Command.CommandId' --output text 2>/dev/null)" || return 1
  for _ in $(seq 1 60); do
    sleep "$SSM_POLL_SECS"
    state="$(aws ssm get-command-invocation --command-id "$command_id" --instance-id "$BOX_ID" \
      --region "$REGION" --query Status --output text 2>/dev/null || echo Pending)"
    [ "$state" != InProgress ] && [ "$state" != Pending ] && break
  done
  [ "$state" = Success ] || return 1
  aws ssm get-command-invocation --command-id "$command_id" --instance-id "$BOX_ID" --region "$REGION" \
    --query StandardOutputContent --output text
}

# Prints "ok <signature>" when the box looks settled, otherwise "wait <why>". The signature names
# every image the box runs, so two checks agree only when nothing changed between them.
box_state() {
  local report compose ps name image wanted signature
  report="$(box_run "cd ${BOX_DIR} && cat compose.json && echo ===PS=== && docker compose -f compose.json ps --format '{{.Service}} {{.Status}}'")" \
    || { echo "wait could not read the box"; return; }
  compose="${report%%===PS===*}"
  ps="${report#*===PS===}"
  for name in $EXPECTED_SERVICES; do
    printf '%s\n' "$ps" | grep -E "^${name} Up " | grep -qvE " Up (Less than a second|[0-4] seconds?)|Restarting" \
      || { echo "wait ${name} is not up and settled"; return; }
  done
  signature=""
  for name in $EXPECTED_SERVICES; do
    image="$(printf '%s' "$compose" | jq -r --arg n "$name" '.services[$n].image // empty' 2>/dev/null)"
    [ "$name" = caddy ] || [ -n "$image" ] || { echo "wait ${name} is not in the box's Compose file"; return; }
    if [ -n "$TASK_DEFINITION" ] && [ "$name" != caddy ]; then
      wanted="$(aws ecs describe-task-definition --task-definition "$TASK_DEFINITION" --region "$REGION" \
        --query "taskDefinition.containerDefinitions[?name=='${name}'].image | [0]" --output text 2>/dev/null)"
      [ "$image" = "$wanted" ] || { echo "wait ${name} runs ${image}, ${TASK_DEFINITION} has ${wanted}"; return; }
    fi
    signature="${signature}${name}=${image} "
  done
  echo "ok ${signature}"
}

wait_for_settled_roll() {
  echo "==> waiting for the roll to settle (box ${BOX_STACK}, stack widget-platform; timeout ${SETTLE_TIMEOUT_SECS}s)"
  local start=$SECONDS previous="" status stacks state signature why s
  BOX_ID="$(aws cloudformation describe-stacks --stack-name "$BOX_STACK" --region "$REGION" \
    --query "Stacks[0].Outputs[?OutputKey=='InstanceId'].OutputValue" --output text 2>/dev/null)"
  if [ -z "$BOX_ID" ] || [ "$BOX_ID" = None ]; then
    echo "==> no instance in stack ${BOX_STACK}. The smoke was NOT run." >&2
    return 20
  fi
  while true; do
    stacks=""
    for s in $WATCHED_STACKS; do
      status="$(stack_status "$s")"
      case "$status" in
        *ROLLBACK*|*FAILED*)
          echo "==> roll did not settle: stack ${s} is ${status}. The smoke was NOT run." >&2
          return 20 ;;
      esac
      stacks="${stacks}${s}=${status:-unreadable} "
    done
    if printf '%s' "$stacks" | tr ' ' '\n' | grep -v '^$' | grep -qvE '=(CREATE|UPDATE)_COMPLETE$'; then
      state="wait ${stacks}"
    else
      state="$(box_state)"
    fi
    if [ "${state%% *}" = "ok" ]; then
      signature="${stacks}${state#ok }"
      if [ "$signature" = "$previous" ]; then
        echo "    -> settled on ${state#ok } (two consecutive checks agree)"
        return 0
      fi
      echo "    -> looks settled (${state#ok }); confirming in ${SETTLE_CHECK_INTERVAL_SECS}s"
      previous="$signature"
    else
      why="${state#wait }"
      echo "    -> not yet: ${why}"
      previous=""
    fi
    if [ $((SECONDS - start + SETTLE_CHECK_INTERVAL_SECS)) -gt "$SETTLE_TIMEOUT_SECS" ]; then
      echo "==> roll did not settle within ${SETTLE_TIMEOUT_SECS}s (last: ${state#wait }). The smoke was NOT run." >&2
      return 20
    fi
    sleep "$SETTLE_CHECK_INTERVAL_SECS"
  done
}

# Ids of the workflow_dispatch runs that exist now, one per line.
dispatch_run_ids() {
  gh run list --repo "$REPO" --workflow "$WORKFLOW" --event workflow_dispatch --limit 50 \
    --json databaseId --jq '.[].databaseId' 2>/dev/null
}

print_failed_checks() {
  local run_id="$1" log names
  log="$(gh run view "$run_id" --repo "$REPO" --log 2>/dev/null || true)"
  # Log lines are "<job>\t<step>\t<timestamp> <text>"; a smoke that prints "  <check>... FAILED: <why>"
  # for each failing check is listed by name.
  names="$(printf '%s\n' "$log" | awk -F'\t' 'NF >= 3 { print $3 }' | sed -E 's/^[0-9T:.-]+Z //' \
    | grep -E '\.\.\. FAILED:' | sed -E 's/^ +//' || true)"
  if [ -n "$names" ]; then
    echo "    failed checks:"
    printf '%s\n' "$names" | sed 's/^/      - /'
  else
    echo "    (no failed check names in the log; the run may have failed before the checks. Last log lines:)"
    printf '%s\n' "$log" | tail -n 15 | sed 's/^/      /'
  fi
}

run_smoke() {
  local before run_id="" waited=0 url conclusion status
  if ! before="$(dispatch_run_ids)"; then
    echo "==> could not list the smoke workflow's runs, so it was NOT dispatched (it could not be told apart afterwards). Run it by hand: ${MANUAL_DISPATCH}" >&2
    return 23
  fi

  echo "==> dispatching the production smoke: ${MANUAL_DISPATCH}"
  if ! gh workflow run "$WORKFLOW" --repo "$REPO" --ref "$SMOKE_REF"; then
    echo "==> could not dispatch the smoke workflow. Deploy succeeded; run it by hand: ${MANUAL_DISPATCH}" >&2
    return 23
  fi

  # The dispatch call does not return the run, so find the workflow_dispatch run that was not there
  # before it (scheduled runs are never candidates).
  while [ -z "$run_id" ] && [ "$waited" -lt 180 ]; do
    sleep 2
    waited=$((waited + 2))
    run_id="$(comm -13 <(printf '%s\n' "$before" | sort) <(dispatch_run_ids | sort) | sort -n | tail -n 1)"
  done
  if [ -z "$run_id" ]; then
    echo "==> dispatched, but the new run never appeared. Deploy succeeded; check https://github.com/${REPO}/actions/workflows/${WORKFLOW}" >&2
    return 23
  fi
  url="https://github.com/${REPO}/actions/runs/${run_id}"
  echo "==> smoke run ${run_id}: ${url}"
  if [ "${SMOKE_ASYNC:-}" = "1" ]; then
    echo "==> deploy succeeded; the smoke is still running (SMOKE_ASYNC=1), so its result is NOT known yet."
    echo "    Watch it: gh run watch ${run_id} --repo ${REPO}   or open ${url}"
    return 0
  fi

  waited=0
  while true; do
    status="$(gh run view "$run_id" --repo "$REPO" --json status --jq .status 2>/dev/null || true)"
    [ "$status" = "completed" ] && break
    if [ "$waited" -ge "$SMOKE_RUN_TIMEOUT_SECS" ]; then
      echo "==> deploy succeeded, but the smoke run did not finish within ${SMOKE_RUN_TIMEOUT_SECS}s: see ${url}" >&2
      return 23
    fi
    sleep 5
    waited=$((waited + 5))
  done

  conclusion="$(gh run view "$run_id" --repo "$REPO" --json conclusion --jq .conclusion || true)"
  echo "==> smoke conclusion: ${conclusion}  ${url}"
  if [ "$conclusion" = "success" ]; then
    echo "==> deploy succeeded, post-deploy smoke passed."
    return 0
  fi
  print_failed_checks "$run_id"
  echo "==> deploy succeeded, post-deploy smoke FAILED: see ${url}" >&2
  return 22
}

rc=0
wait_for_settled_roll || rc=$?
[ "$rc" -eq 0 ] || exit "$rc"

if [ "${DRY_RUN:-}" = "1" ]; then
  echo "==> DRY_RUN=1: would dispatch: ${MANUAL_DISPATCH}"
  newest="$(dispatch_run_ids | sort -n | tail -n 1 || true)"
  if [ -n "$newest" ]; then
    echo "    then pick the workflow_dispatch run that appears after it; the newest existing one is"
    echo "    https://github.com/${REPO}/actions/runs/${newest} (not the one it would wait for)"
  else
    echo "    (no workflow_dispatch runs exist yet)"
  fi
  echo "    then wait for it and report its conclusion and failed checks. Nothing dispatched."
  exit 0
fi

run_smoke || rc=$?
exit "$rc"
